        var right=new DockPanel();Grid.SetColumn(right,2);root.Children.Add(right);var help=DesignerWindow.Text("Every selection creates a new item on save. Empty slots are allowed. Two-hand weapons occupy both hands. Shirt/tabard are optional outfit copies and do not count toward the client's 17-member set limit.",12);help.Margin=new Thickness(0,0,0,10);DockPanel.SetDock(help,Dock.Top);right.Children.Add(help);var actions=new WrapPanel{Margin=new Thickness(0,0,0,10)};DockPanel.SetDock(actions,Dock.Top);right.Children.Add(actions);DesignerWindow.Button("Edit copy draft",actions).Click+=async(_,_)=>await EditPiece();DesignerWindow.Button("Remove selected copy",actions).Click+=(_,_)=>{if(pieces.SelectedItem is SetPieceDraft piece){draft.Remove(piece);Render();}};pieces.Height=230;pieces.ItemsSource=draft;DockPanel.SetDock(pieces,Dock.Top);right.Children.Add(pieces);right.Children.Add(DesignerWindow.Preview(piecePreview,"NEW ITEM DRAFT · BASE ITEM STILL EXISTS"));pieceViews.Items.Add(new TabItem{Header="Equipment layout",Content=equipment});pieceViews.Items.Add(new TabItem{Header="Find base items & copies",Content=root});equipment.SelectionChanged+=row=>{if(row?.Key is SetPieceDraft piece)pieces.SelectedItem=piece;};equipment.EditRequested+=async row=>{if(row.Key is SetPieceDraft piece){pieces.SelectedItem=piece;await EditPiece();}};equipment.DropRequested+=row=>{if(row.Key is SetPieceDraft piece)EditPieceDrops(piece);};equipment.EmptySlotSelected+=target=>{slot.SelectedItem=slot.Items.Cast<FilterChoice>().First(c=>c.Id==target);pieceViews.SelectedIndex=1;};pieces.MouseDoubleClick+=async(_,_)=>await EditPiece();return pieceViews;
    }
    private FrameworkElement BonusPage()
    {
        var root=new DockPanel{Margin=new Thickness(10)};var help=DesignerWindow.Text("Choose the pieces first, then add bonus spells and piece thresholds. Edit bonus values creates spells private to this new set. All changes remain drafts until Review & create set.",12);DockPanel.SetDock(help,Dock.Top);root.Children.Add(help);var actions=new WrapPanel{Margin=new Thickness(0,12,0,10)};DockPanel.SetDock(actions,Dock.Top);root.Children.Add(actions);Field(actions,"Required pieces",threshold);DesignerWindow.Button("Add bonus…",actions).Click+=(_,_)=>PickBonus(false);DesignerWindow.Button("Change spell…",actions).Click+=(_,_)=>PickBonus(true);DesignerWindow.Button("Apply piece threshold",actions).Click+=(_,_)=>{if(bonuses.SelectedItem is ContentRow row&&TryThreshold(out int n)){var next=row with{Pieces=n};bonusDraft[bonusDraft.IndexOf(row)]=next;bonuses.SelectedItem=next;Render();}};DesignerWindow.Button("Explain selected…",actions).Click+=(_,_)=>{if(bonuses.SelectedItem is ContentRow selected){var saved=selected with{Bonus=null};new EffectExplanationWindow("Set bonus explanation",refs.Explain(saved.SpellId,saved),refs.Explain(selected.SpellId,selected)){Owner=this}.ShowDialog();}};DesignerWindow.Button("Edit bonus values…",actions).Click+=async(_,_)=>await EditBonus();DesignerWindow.Button("Remove bonus",actions).Click+=(_,_)=>{if(bonuses.SelectedItem is ContentRow row){bonusDraft.Remove(row);Render();}};
