    private void EditPieceDrops(SetPieceDraft piece){if(busy||world is null)return;var editor=new DropLocationWindow(piece.Draft,piece.Drops,world){Owner=this};if(editor.ShowDialog()==true&&editor.Result is {} plan){var updated=piece with{Drops=plan};draft[draft.IndexOf(piece)]=updated;Render();equipment.SelectKey(updated);feedback.Text="Drop locations updated in the copy draft. Review & create set saves them with the new item.";}}
    private FrameworkElement DropPage(){var root=new DockPanel{Margin=new Thickness(10)};DockPanel.SetDock(dropSummary,Dock.Top);dropSummary.Margin=new Thickness(0,0,0,12);root.Children.Add(dropSummary);var locations=new Button{Content="Choose instance & boss / world drops…",HorizontalAlignment=HorizontalAlignment.Left,Margin=new Thickness(0,0,0,12)};DockPanel.SetDock(locations,Dock.Top);root.Children.Add(locations);var note=DesignerWindow.Text("Eligible normal outdoor creatures only. Areas too low for the piece, bosses, dungeons, scripted/scaling creatures, unknown zones and loot tables shared with ineligible creatures are excluded. Rates are per piece before server multipliers. Selecting a copy below shows its full target list. Select instance bosses to replace world drops for a piece.",12);note.Margin=new Thickness(0,0,0,12);DockPanel.SetDock(note,Dock.Top);root.Children.Add(note);var dropItemPanel=new StackPanel();var chooser=new ComboBox{DisplayMemberPath="Name",ItemsSource=draft,Margin=new Thickness(0,0,0,12)};DockPanel.SetDock(chooser,Dock.Top);root.Children.Add(chooser);locations.Click+=(_,_)=>{if(world is null||chooser.SelectedItem is not SetPieceDraft piece)return;var editor=new DropLocationWindow(piece.Draft,piece.Drops,world){Owner=this};if(editor.ShowDialog()==true&&editor.Result is {} plan){int index=draft.IndexOf(piece);var updated=piece with{Drops=plan};draft[index]=updated;chooser.SelectedItem=updated;Render();}};chooser.SelectionChanged+=(_,_)=>{if(chooser.SelectedItem is SetPieceDraft piece){drops.ItemsSource=piece.Drops.Targets;TooltipView.Fill(dropItemPanel,ItemTooltip.Build(piece.Draft,catalog.Tooltips,catalog.Items.ToDictionary(i=>i.Id)));ItemVisualPreview.Outfit(dropItemPanel,draft.ToDictionary(p=>p.Slot,p=>p.Draft));dropSummary.Text=piece.Name+"\n"+piece.Drops.Summary;}else{drops.ItemsSource=null;TooltipView.Fill(dropItemPanel,Array.Empty<TooltipLine>());dropSummary.Text="Select a copy to inspect its exact world-drop targets.";}};tabs.SelectionChanged+=(_,e)=>{if(ReferenceEquals(e.Source,tabs)&&tabs.SelectedIndex==2&&chooser.SelectedItem is null&&draft.Count>0)chooser.SelectedIndex=0;};var dropSplit=new Grid();dropSplit.ColumnDefinitions.Add(new());dropSplit.ColumnDefinitions.Add(new());dropSplit.Children.Add(drops);var dropVisual=DesignerWindow.Preview(dropItemPanel,"SELECTED COPY");Grid.SetColumn(dropVisual,1);dropSplit.Children.Add(dropVisual);root.Children.Add(dropSplit);return root;}
    private void FilterBases(){if(slot.SelectedItem is not FilterChoice target)return;string q=search.Text.Trim();int quality=(rarity.SelectedItem as FilterChoice)?.Id??-1;bases.ItemsSource=catalog.Items.Where(i=>itemKinds.Matches(i)&&GearDesign.Targets(i).Contains(target.Id)&&(quality<0||i.Quality==quality)&&CatalogSearch.Item(i,q)).ToList();if(bases.Items.Count>0)bases.SelectedIndex=0;}
    private decimal Chance(){if(!decimal.TryParse(chance.Text,NumberStyles.AllowDecimalPoint|NumberStyles.AllowLeadingSign,CultureInfo.InvariantCulture,out decimal value)||value is <=0 or >1)throw new InvalidOperationException("Enter a drop chance greater than 0 and no more than 1%, using a decimal point.");return value;}
    internal async Task AddPiece(int id,int target)
    {
        if(busy||world is null)return;busy=true;body.IsEnabled=create.IsEnabled=false;try{var source=await ItemCloning.LoadAsync(id);if(closed)return;var fields=new Dictionary<string,string>(source.Item.Current.Fields,StringComparer.OrdinalIgnoreCase){["Display"]=name.Text.Trim()+" · "+GearDesign.EquipmentSlots[target],["ItemSet"]="0"};if(!string.IsNullOrWhiteSpace(bulkLevel.Text))fields["ItemLevel"]=ParseLevel(bulkLevel.Text,1,1000,"item level").ToString();if(!string.IsNullOrWhiteSpace(bulkRequired.Text))fields["RequiredLevel"]=ParseLevel(bulkRequired.Text,0,60,"required level").ToString();var item=new CatalogItem(fields);if(target==16&&draft.Any(p=>p.Slot==15&&p.Draft.Slot==17))throw new InvalidOperationException("Remove the two-handed main-hand copy before adding an off-hand item.");if(target==15&&item.Slot==17&&draft.Any(p=>p.Slot==16))throw new InvalidOperationException("Remove the off-hand copy before adding a two-handed weapon.");var piece=new SetPieceDraft(target,source,item,world.Plan(item,Chance()));var previous=draft.FirstOrDefault(p=>p.Slot==target);if(previous is not null){if(MessageBox.Show(this,$"Replace the unsaved copy in {previous.SlotName}?","Replace slot",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;draft.Remove(previous);}draft.Add(piece);pieces.SelectedItem=piece;pieceViews.SelectedIndex=0;feedback.Text="Copy added to draft. The original item has not been changed.";Render();equipment.SelectKey(piece);}catch(Exception ex){feedback.Text=ex.Message;}finally{busy=false;body.IsEnabled=true;Render();}
    }
    private static int ParseLevel(string text,int min,int max,string title){if(!int.TryParse(text,out int value)||value<min||value>max)throw new InvalidOperationException($"Enter {title} from {min} to {max}.");return value;}
    private void ApplyBulk(){if(busy||world is null)return;try{int? ilvl=string.IsNullOrWhiteSpace(bulkLevel.Text)?null:ParseLevel(bulkLevel.Text,1,1000,"item level"),required=string.IsNullOrWhiteSpace(bulkRequired.Text)?null:ParseLevel(bulkRequired.Text,0,60,"required level");decimal rate=Chance();var updated=draft.Select(p=>{var fields=new Dictionary<string,string>(p.Draft.Fields,StringComparer.OrdinalIgnoreCase);if(ilvl.HasValue)fields["ItemLevel"]=ilvl.Value.ToString();if(required.HasValue)fields["RequiredLevel"]=required.Value.ToString();var item=new CatalogItem(fields);ItemEditing.Validate(p.Source.Item,item);return p with{Draft=item,Drops=WorldDrops.Replan(world,item,p.Drops.Mode=="Boss"?p.Drops:p.Drops with{Chance=rate})};}).ToArray();draft.Clear();foreach(var p in updated)draft.Add(p);Render();feedback.Text="Levels and drop previews updated on copies only.";}catch(Exception ex){feedback.Text=ex.Message;}}
    private async Task EditPiece(){if(busy||pieces.SelectedItem is not SetPieceDraft piece||world is null)return;try{decimal rate=Chance();var editor=new ItemEditorWindow(catalog,piece.Source.Item.Current.Id,draft:piece.Draft){Owner=this};if(editor.ShowDialog()==true&&editor.AcceptedDraft is {} edited){draft[draft.IndexOf(piece)]=piece with{Draft=edited,Drops=WorldDrops.Replan(world,edited,piece.Drops.Mode=="Boss"?piece.Drops:piece.Drops with{Chance=rate})};Render();}}catch(Exception ex){feedback.Text=ex.Message;}}
    private bool TryThreshold(out int count){count=0;if(!int.TryParse(threshold.Text,out count)||count<1||count>draft.Count(p=>p.CountsForSet)){feedback.Text="Choose a threshold from 1 to the number of bonus-counting pieces.";return false;}return true;}
    private void PickBonus(bool replace){if(busy||!TryThreshold(out int count))return;var current=replace?bonuses.SelectedItem as ContentRow:null;if(replace&&current is null)return;var picker=new SpellPicker(refs,false,current?.SpellId){Owner=this};if(picker.ShowDialog()!=true||picker.Selected is not {} selected)return;var row=new ContentRow(0,0,selected.SpellId,count);if(current is not null)bonusDraft[bonusDraft.IndexOf(current)]=row;else bonusDraft.Add(row);bonuses.SelectedItem=row;Render();}
    private async Task EditBonus(){if(busy||bonuses.SelectedItem is not ContentRow row)return;busy=true;body.IsEnabled=false;try{var source=row.Bonus?.Source??await BonusSpells.LoadAsync(row.SpellId);var editor=new BonusValueWindow(source,refs.Data,row.Bonus){Owner=this};if(editor.ShowDialog()==true&&editor.Result is {} bonus){var next=row with{Bonus=bonus};bonusDraft[bonusDraft.IndexOf(row)]=next;bonuses.SelectedItem=next;Render();}}catch(Exception ex){feedback.Text=ex.Message;}finally{busy=false;body.IsEnabled=true;Render();}}
    private async Task RefreshWorld(){if(busy)return;busy=true;body.IsEnabled=create.IsEnabled=false;try{feedback.Text="Resolving outdoor creatures and map zones…";var loaded=await WorldDropCatalog.LoadAsync();if(closed)return;decimal rate=Chance();world=loaded;for(int n=0;n<draft.Count;n++)draft[n]=draft[n] with{Drops=WorldDrops.Replan(world,draft[n].Draft,draft[n].Drops.Mode=="Boss"?draft[n].Drops:draft[n].Drops with{Chance=rate})};feedback.Text="World drops refreshed. Review the creature lists before creating the set.";}catch(Exception ex){feedback.Text=ex.Message;}finally{busy=false;body.IsEnabled=true;Render();}}
    private void RenderPiece(){if(pieces.SelectedItem is SetPieceDraft selected&&!Equals(equipment.Selection?.Key,selected))equipment.SelectKey(selected);TooltipView.Fill(piecePreview,Array.Empty<TooltipLine>());if(pieces.SelectedItem is SetPieceDraft piece){var lookup=catalog.Items.ToDictionary(i=>i.Id);lookup[piece.Draft.Id]=piece.Draft;TooltipView.Fill(piecePreview,ItemTooltip.Build(piece.Draft,catalog.Tooltips,lookup,60));ItemVisualPreview.Outfit(piecePreview,draft.ToDictionary(p=>p.Slot,p=>p.Draft));}}
    private void Render()
    {
        if(closed)return;equipment.Bind(draft.Select(p=>new EquipmentViewItem(p,p.Draft,p.Slot)),catalog.Tooltips,catalog.Items.ToDictionary(i=>i.Id));int count=draft.Count(p=>p.CountsForSet);summary.Text=$"{draft.Count} new item copies · {count} set members · {bonusDraft.Count} bonuses";create.IsEnabled=false;try{SetCreation.Validate(name.Text.Trim(),draft.ToArray(),bonusDraft.ToArray(),refs);create.IsEnabled=!busy&&world is not null;}catch(Exception ex){summary.Text+="\n"+ex.Message;}var color=draft.FirstOrDefault()?.Draft.NameBrush.ToString()??"#A335EE";var lines=new List<TooltipLine>{new(name.Text,color,Size:18,Bold:true),new($"New equipment set · {count} bonus-counting pieces",ItemTooltip.Gold)};foreach(var piece in draft.OrderBy(p=>p.Slot))lines.Add(new(piece.Name+(piece.CountsForSet?"":" [outfit only]"),ItemTooltip.Green));lines.Add(new("",Size:5));foreach(var row in bonusDraft.OrderBy(b=>b.Pieces))lines.Add(new($"({row.Pieces}) Set: {row.Bonus?.Description(refs.Data)??refs.Data.SpellDescription(row.SpellId)}",ItemTooltip.Green));TooltipView.Fill(setPreview,lines);RenderPiece();
    }
    private string Review()=>string.Join("\n\n",draft.Select(p=>$"{p.SlotName}: {p.Name}\nBase {p.Source.Item.Current.Id} remains unchanged; new ID allocated on save.\nItem level {p.Level}, required level {p.RequiredLevel}.\n{p.Drops.Summary}\nZones: "+string.Join(", ",p.Drops.Targets.Select(t=>t.Zones).Distinct())))+"\n\nSET BONUSES\n"+string.Join("\n",bonusDraft.Select(b=>$"({b.Pieces}) {b.Bonus?.Description(refs.Data)??refs.Data.SpellDescription(b.SpellId)}"));
    private async Task Save(){if(busy||world is null)return;try{if(draft.Any(p=>p.Drops.Mode!="Boss"&&p.Drops.Chance!=Chance()))throw new InvalidOperationException("The chance changed. Refresh world drops before reviewing.");var frozen=draft.ToArray();var bonuses=bonusDraft.ToArray();SetCreation.Validate(name.Text.Trim(),frozen,bonuses,refs);var review=new ContentReviewWindow("new set, duplicate items & world drops",name.Text,"No new set or items exist yet. All selected base items remain unchanged.",Review()){Owner=this};if(review.ShowDialog()!=true)return;busy=true;body.IsEnabled=create.IsEnabled=false;feedback.Text="Creating the set, copies, bonuses and world drops in one transaction…";Result=await SetCreation.SaveAsync(name.Text.Trim(),frozen,bonuses,refs);busy=false;DialogResult=true;}catch(Exception ex){feedback.Text="Could not create set: "+ex.Message;}finally{busy=false;body.IsEnabled=true;Render();}}
    internal void SetVerificationName(string value){name.Text=value;}
    internal void AddVerificationBonus(ContentRow row){bonusDraft.Add(row);Render();}
    internal void SelectVerificationTab(int index){tabs.SelectedIndex=index;}
    internal void DiscardVerification(){discard=true;}
}
